package net.zartra.gui;
import java.util.*;
final class VariableStore { private final Map<String,String> global=new HashMap<String,String>(); private final Map<UUID,Map<String,String>> player=new HashMap<UUID,Map<String,String>>(); void setGlobal(String key,String value){if(value==null)global.remove(key);else global.put(key,value);} String global(String key){return global.get(key);} java.util.Map<String,String> globals(){return new java.util.HashMap<String,String>(global);} void setPlayer(UUID id,String key,String value){Map<String,String> map=player.get(id);if(map==null){map=new HashMap<String,String>();player.put(id,map);}if(value==null)map.remove(key);else map.put(key,value);} String player(UUID id,String key){Map<String,String> map=player.get(id);return map==null?null:map.get(key);} }
